function updateButtons(){if(!active)return;$('#play').textContent=running?'Ⅱ Пауза':Number.isFinite(transitionDuration())&&time>=transitionDuration()?(active.id==='interference'?'▶ Почати нове накопичення':'▶ Повторити перехід'):(active.id==='interference'?(params.mode==='photons'?'▶ Почати накопичення':'▶ Почати анімацію'):'▶ Почати дослід');$('#step').disabled=running;$('#status').textContent=!animatedIds.includes(active.id)?'Результат оновлюється одразу':running?'Дослід триває':Number.isFinite(transitionDuration())&&time>=transitionDuration()?(active.id==='interference'?'Накопичення завершено':'Перехід завершено'):time?'Пауза':'Готово до запуску'}
function reset(){clearInterval(skyTimer);skyTimer=null;if(active?.id==='sky'&&$('#skyRise'))$('#skyRise').textContent='▶ Схід / захід';running=false;cancelAnimationFrame(frame);time=0;photons=[];buildCDF();syncControls();updateButtons();render()}
function buildCDF(){cdf=[];if(active?.id!=='interference')return;let extent=.015,sum=0;for(let i=0;i<2000;i++){let x=-extent+2*extent*(i+.5)/2000;sum+=P.fringe(x,params);cdf.push({x,sum})}for(let q of cdf)q.sum/=sum}
function updatePhotons(){if(active?.id!=='interference'||params.mode!=='photons')return;let count=Math.min(12000,Math.floor(time*params.rate+1e-8));while(photons.length<count){let u=Math.random(),lo=0,hi=cdf.length-1;while(lo<hi){let m=(lo+hi)>>1;if(cdf[m].sum<u)lo=m+1;else hi=m}photons.push({x:cdf[lo].x,jitter:Math.random()})}}
function render(animated=false){if(!active||!$('#scene'))return;if(active.id==='sky'&&!requestSky(params,()=>{if(active?.id==='sky')render()},message=>{if($('#status'))$('#status').textContent=message})){const c=$('#scene'),ctx=c.getContext('2d');ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#181513';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='white';ctx.font='24px NAMU, sans-serif';ctx.textAlign='center';ctx.fillText('Обчислюю світло в атмосфері…',c.width/2,c.height/2);ctx.restore();const solar=$('#sunScene'),sc=solar.getContext('2d');sc.save();sc.setTransform(1,0,0,1,0,0);sc.clearRect(0,0,solar.width,solar.height);sc.restore();$('#live').textContent='Обчислення для нових параметрів…';$('#worked').textContent='Очікування нового результату…';const chart=$('#curve');chart.getContext('2d').clearRect(0,0,chart.width,chart.height);drawCache=null;$('#record').disabled=true;return}if(active.id==='sky'){$('#record').disabled=false;$('#status').textContent='Спектральний розрахунок завершено'}let isAnim=animatedIds.includes(active.id);if(!animated||isAnim)drawScene($('#scene'),active,params,time,photons);if(active.id==='sky')drawSunCloseup($('#sunScene'),params);if((!animated||active.id==='wave')&&!(active.id==='sky'&&params.mode==='mars')){drawCache=chartData(active,params,time);if(active.id==='sky')$('#curveTitle').textContent=params.skyPlot==='tau'?'Як газ розсіює різні довжини хвиль':params.skyPlot==='shape'?'Форми спектрів: небо й пряме світло':'Спектр світла з вибраного напрямку неба';$('#curve').setAttribute('aria-label',drawCache.xlabel+'; '+drawCache.ylabel);drawChart($('#curve'),drawCache)}if(!animated){$('#worked').innerHTML=mathMarkup(worked(active.id,params));if(active.id==='polarization')renderWaterCompare(params);}let out=active.id==='sky'?(()=>{let q=selectedSky(params);return {'Тиск (Па)':q.q.pressure,'Висота зорі (град)':params.sun,'Кут розсіювання (град)':q.theta,'Масштаб висоти газу (км)':q.q.H,'Прискорення вільного падіння (м/с²)':q.q.g,'Середня маса молекули (а.о.м.)':q.meanMass,'Оптична товщина газу 550 нм':q.gasTau550,'Оптична товщина пилу 550 нм':params.dust,'Інтегральний сигнал неба (відн./ср)':q.relative}})():P.outputs(active.id,params,time);$('#live').innerHTML=Object.entries(out).map(([k,v])=>`<span>${mathMarkup(k)}: <b>${active.id==='sky'&&(k.includes('Оптична товщина газу')||k.includes('Інтегральний сигнал'))?fmt(v,6):number(v)}</b></span>`).join('');$('#time').textContent=`Час анімації: ${number(time)} с${active.id==='interference'?' · '+photons.length+' реєстрацій (максимум 12 000 у полі)':''}`}
function renderWaterCompare(p){let box=$('#waterCompare');box.hidden=p.mode!=='water';$('#waterBeamTools').hidden=box.hidden;if(box.hidden)return;let q=P.polarization(p),light=P.waterLight(p),signal=light.detailBefore,trans=light.detailTransmission;let tools=$('#waterBeamTools');tools.hidden=false;tools.innerHTML=`<strong>До ока надходять два потоки світла</strong><p>Відблиск від поверхні + світло від предметів під водою. На 3D схемі нижче показано лише <b>${p.waterBeam==='detail'?'світло від підводної деталі':'відблиск'}</b>. Картинка з рибою поєднує обидва потоки. Масштаб 3D нормовано до входу вибраного потоку; абсолютні інтенсивності наведено нижче.</p>${active.fields.filter(f=>f.key==='waterBeam').map(f=>fieldHTML({...f,key:'waterBeamScene'})).join('')}`;const beamControl=tools.querySelector('select');beamControl.value=p.waterBeam;beamControl.addEventListener('change',()=>{params.waterBeam=beamControl.value;$('#p-waterBeam').value=params.waterBeam;try{sessionStorage.setItem('light-params-polarization',JSON.stringify(params))}catch{}render()});const view=(name,glare,fish,tag)=>{let g=Math.min(.96,glare/(glare+fish+1e-30)),brightness=(glare+fish)>1e-14?(p.waterExposure==='contrast'?1:Math.min(1,((glare+fish)/(q.glareBefore+signal))**(1/2.2))):0;return `<div><strong>${name}</strong><svg viewBox="0 0 300 150" role="img" aria-label="Умовне порівняння видимості під водою"><rect width="300" height="150" fill="#264b61"/><path d="M0 120Q80 90 160 115T300 105V150H0" fill="#426f76"/><g opacity="${fish>1e-14?1:0}"><ellipse cx="155" cy="92" rx="35" ry="14" fill="#b7cdb0"/><path d="M125 92L100 73V111Z" fill="#b7cdb0"/><circle cx="175" cy="88" r="3" fill="#183741"/><path d="M15 145Q32 95 20 85M50 150Q58 100 77 94M260 150Q245 100 259 85" fill="none" stroke="#82a8a0" stroke-width="5"/></g><g opacity="${g}"><rect width="300" height="150" fill="#d8e5e8"/><path d="M0 40Q40 5 85 40T175 37T300 40M0 90Q55 70 110 90T220 87T300 95" fill="none" stroke="white" stroke-width="17"/></g><rect width="300" height="150" fill="black" opacity="${1-brightness}"/></svg><small>${tag}</small></div>`};box.innerHTML=`<p><strong>Світло, що доходить до ока після фільтрів:</strong><br>відблиск ${fmt(100*light.glareAfter,6)} % + підводна деталь ${fmt(100*light.detailAfter,4)} % = разом ${fmt(100*light.totalAfter,4)} % від освітлення.<br>${light.totalAfter<1e-14?'Обидва потоки погашено. Зображення чорне.':'Навіть коли відблиск майже погашено, світло від деталі може проходити.'}</p><div class="waterViews">${view('Без фільтра',q.glareBefore,signal,`Відблиск: ${fmt(100*q.glareBefore,4)} % · деталь: ${fmt(100*signal,3)} % від освітлення`)}${view('Через обрані фільтри',q.glareAfter,signal*trans,`Відблиск: ${fmt(100*q.glareAfter,4)} % · деталь: ${fmt(100*signal*trans,3)} % від освітлення`)}</div><p>Умовна підводна деталь: її світло в оці вважаємо неполяризованим, з інтенсивністю 0,02 від потоку освітлення. Відблиск розраховано за Френелем; деталь також тьмяніє крізь фільтри. ${p.waterExposure==='contrast'?'Яскравість двох картинок нормовано окремо для порівняння контрасту; це не порівняння абсолютної яскравості.':'Однакова умовна експозиція: після фільтрів зображення темнішає зі зменшенням сумарного сигналу.'} Значення наведено у відсотках від одного й того самого потоку освітлення. Відображення картинки наближене; це не розрахунок оптики підводного зображення. Колір і зображення умовні.</p>`}
function worked(id,p){if(id==='sky'&&p.mode==='simulation'){let q=selectedSky(p);return `P = 10<sup>${fmt(p.logP)}</sup> = ${fmt(q.q.pressure)} Па<br>H = k<sub>B</sub>T/(m̄g) = ${fmt(q.q.H)} км<br>Кут розсіювання: ${fmt(q.theta)}°<br>Частки [N₂, O₂, CO₂, H₂]: ${q.q.f.map(x=>fmt(100*x,1)+'%').join(', ')}<br>τ<sub>dust</sub>(550 нм) = ${p.dust}. Сферичний перенос із повторними розсіюваннями та відбиттям поверхні.<br>Інтегральний сигнал = ${fmt(q.relative,6)} ± ${fmt(q.stderr,6)} відн./ср (верхня оцінка 1σ для повторних розсіювань). Вона не охоплює похибку оптичних даних і сітки.${q.cut?`<br>Увага: ${q.cut} траєкторій досягли граничного порядку; потрібна перевірка збіжності.`:""}`}if(id==='sky'&&p.mode==='mars')return p.marsTime==='sunset'?'На заході шлях світла крізь пил довший. Блакитне розсіяне світло зосереджене біля напряму Сонця, а не по всьому небі. Відтінки схеми підібрано для пояснення спостережень; спектральних обчислень тут немає.':'Удень завислий мінеральний пил надає небу часто жовтувато-рудого відтінку. Сам по собі CO₂ цього не пояснює. Відтінки схеми умовні; це не розрахунок спектра.';let q;switch(id){case 'wave':return `ν = c/λ = 299 792 458 / (${p.lambda} × 10⁻⁹) = <strong>${fmt(P.C/(p.lambda*1e-9))} Гц</strong><br>E = hc/λ = <strong>${fmt(P.H*P.C/(p.lambda*1e-9)/P.EV)} еВ</strong><br>I/Iref = ${fmt(p.amp)}² = <strong>${fmt(p.amp**2)}</strong>`;case 'interference':return `Δx ≈ λL/d = (${p.lambda} × 10⁻⁹ × ${fmt(p.L)}) / (${fmt(p.d)} × 10⁻³) = <strong>${fmt(p.lambda*1e-9*p.L/(p.d*1e-3)*1000)} мм</strong><br>Екран має сталу шкалу −15…+15 мм: зміна кроку смуг видима без перенормування поля.${p.path?'<br>Когерентність втрачена: дрібних смуг немає. Обчислений крок описує лише порівняльний когерентний випадок.':''}`;case 'diffraction':q=P.outputs(id,p,0);return `${p.kind==='grating'?'sin θ<sub>огин</sub>':'sin θ₁'} = ${p.kind==='circle'?'1,21967 × ':''}λ/a = ${p.kind==='circle'?'1,21967 × ':''}${p.lambda} × 10⁻⁹ / (${fmt(p.width)} × 10⁻⁶)<br>${p.kind==='grating'?'θ<sub>огин</sub>':'θ₁'} = <strong>${fmt(q[p.kind==='grating'?'Кут мінімуму огинаючої (град)':'Кут першого мінімуму (град)'])}°</strong>${p.kind==='grating'?`<br>Перший мінімум ґратки: sin θ₁ = λ/(Nd) = ${p.lambda}/(${p.n} × ${p.spacing} × 1000)<br>θ₁ = <strong>${fmt(q['Кут першого мінімуму (град)'])}°</strong>`:''}`;case 'polarization':q=P.polarization(p);return `Перед першим фільтром I = ${fmt(q.stokes[0],5)} ${p.mode==='water'?'від світла, що падає на воду':'від потоку джерела'}.<br>${q.stages.map((s,i)=>`Фільтр ${i+1}, вісь ${s.angle}°: I<sub>${i+1}</sub> = <strong>${fmt(s.intensity,5)}</strong>`).join('<br>')}<br>Для першого: I<sub>1</sub> = ½[I + Q cos(2θ) + U sin(2θ)]. Для наступних: I<sub>j</sub> = I<sub>j−1</sub> cos²(θ<sub>j</sub> − θ<sub>j−1</sub>).${p.mode==='water'?`<br>R<sub>s</sub> = ${fmt(q.rs,5)}; R<sub>p</sub> = ${fmt(q.rp,5)}; θ<sub>B</sub> = ${fmt(q.brewster,2)}°. Відбиття та вихідний відблиск у результатах подано у % від падаючого на воду світла. Окремий показник пропускання фільтрів подано у % від відблиску перед фільтрами. Ці знаменники різні.`:''}`;case 'refraction':q=P.refraction(p);return p.prism?(()=>{const rows=[400,550,700].map(nm=>{const q=P.prism(nm,p.material,p.prismAngle,p.apex);return `<strong>${nm} нм</strong>: n = ${fmt(q.n,5)}<br>r<sub>1</sub> = arcsin[sin(${q.incidence}°)/${fmt(q.n,5)}] = ${fmt(q.r1)}°<br>r<sub>2</sub> = ${q.apex}° − ${fmt(q.r1)}° = ${fmt(q.r2)}°<br>${q.tir?'Повне внутрішнє відбиття на другій грані.':`e = arcsin[n sin(r<sub>2</sub>)] = ${fmt(q.emergence)}°<br>δ = i + e − A = ${fmt(q.deviation)}°`}`});const b=P.prism(400,p.material,p.prismAngle,p.apex),r=P.prism(700,p.material,p.prismAngle,p.apex);return `Білий вхід: усі кольори 400–700 нм.<br>i = ${b.incidence}°; A = ${b.apex}°.<br><br>${rows.join('<br><br>')}<br><br>Розділення всередині: |r<sub>1,400</sub> − r<sub>1,700</sub>| = <strong>${fmt(Math.abs(b.r1-r.r1))}°</strong><br>Розділення вихідних напрямів: |δ<sub>400</sub> − δ<sub>700</sub>| = <strong>${fmt(Math.abs(b.deviation-r.deviation))}°</strong>. Риска означає, що один із кольорів не виходить через другу грань. Масштаб і збільшені види не змінюють ці обчислення.`})():`n₁ = ${fmt(q.n1,4)}; n₂ = ${fmt(q.n2,4)}<br>sin θ₂ = (${fmt(q.n1,4)}/${fmt(q.n2,4)}) × sin(${p.angle}°)<br>${q.theta===null?'<strong>Значення > 1: повне внутрішнє відбиття.</strong>':`θ₂ = <strong>${fmt(q.theta)}°</strong>`}${q.critical!==null?`<br>θкр = ${fmt(q.critical)}°`:''}`;case 'photoelectric':q=P.photo(p);return `E = hc/λ = <strong>${fmt(q.e)} еВ</strong>; W = ${q.w} еВ<br>${q.e<q.w?'E < W: однофотонного фотоефекту немає.':`Kmax = ${fmt(q.e)} − ${q.w} = <strong>${fmt(q.ke)} еВ</strong><br>Uзуп = ${fmt(q.ke)} В; U = ${fmt(p.voltage)} В`}`;case 'atom':q=P.atom(p);if(q.tabled)return `<strong>${q.species.name} (${q.species.symbol})</strong><br>Верхній стан: ${q.upperLabel}, E = ${fmt(q.eUpper,5)} еВ<br>Нижній стан: ${q.lowerLabel}, E = ${fmt(q.eLower,5)} еВ<br>ΔE = (${fmt(q.upperCm,4)} − ${fmt(q.lowerCm,4)}) см⁻¹ × hc = <strong>${fmt(q.de,5)} еВ</strong><br>λ<sub>вак</sub> = 10⁷ / ${fmt(q.upperCm-q.lowerCm,4)} = <strong>${fmt(q.lambda,3)} нм</strong><br>NIST: ${fmt(q.lambdaTable,5)} нм (${q.medium}).<br><a href="${P.atomSource(p.species)}" target="_blank" rel="noopener">Дані рівнів і ліній NIST ↗</a>`;return `ΔE = 13,5983 × (1/${q.lower}² − 1/${q.upper}²) = <strong>${fmt(q.de)} еВ</strong><br>λ = hc/ΔE = <strong>${fmt(q.lambda,2)} нм</strong>`;case 'molecule':q=P.molecule(p);return p.transition==='fluorescence'?`3,10 еВ = 2,40 еВ + 0,70 еВ<br>λпогл = 399,95 нм; λвипр = <strong>${fmt(q.lambda,2)} нм</strong>`:`ΔE = <strong>${fmt(q.de,6)} еВ</strong><br>λ = hc/ΔE = <strong>${fmt(q.lambda,2)} нм</strong><br>Виділена модельна лінія показана серед інших переходів.`;case 'sky':q=P.sky(p);return `τR(550 нм) = 0,10 × fгаз × ${fmt(p.pressure)} = <strong>${fmt(q.tau550)}</strong><br>Шлях прямого світла в оболонці: <strong>${fmt(q.path,1)} км</strong><br>Для кожної λ застосовуємо exp(−τ), потім інтегруємо одноразове розсіювання. Кольори плашок нормовані за яскравістю.`;default:q=P.star(p);return `λmax = 2,89777 × 10⁶ / ${p.T} = <strong>${fmt(q.peak,1)} нм</strong><br>F = σ × ${p.T}⁴ = <strong>${fmt(q.flux)} Вт/м²</strong><br>L = 4π × (${fmt(p.radius)} × 6,957 × 10⁸)² × F = <strong>${fmt(q.lum)} Вт</strong>`}}
function tick(now){if(!running||!active)return;if(now-last>=32){time+=Math.min((now-last)/1000,.1);last=now;if(Number.isFinite(transitionDuration())&&time>=transitionDuration()){time=transitionDuration();running=false;}updatePhotons();render(true);if(!running){updateButtons();return}}frame=requestAnimationFrame(tick)}
function route(){clearInterval(skyTimer);skyTimer=null;if(active&&['#calculations','#main'].includes(location.hash)){$(location.hash)?.scrollIntoView();return}running=false;cancelAnimationFrame(frame);let hash=location.hash,id=hash.startsWith('#lab/')?hash.slice(5):null;let e=exps.find(q=>q.id===id);if(e){lab(e);scrollTo(0,0)}else if(!active&&main.innerHTML&&['#experiments','#basics'].includes(hash)){$(hash)?.scrollIntoView()}else{active=null;document.title='Світло — INSCIENCE LAB';home();if(['#experiments','#basics'].includes(hash))requestAnimationFrame(()=>$(hash)?.scrollIntoView());else scrollTo(0,0)}}
function record(){let out=P.outputs(active.id,params,time),values={};for(let f of active.fields)if(typeof params[f.key]==='number'&&!$('#p-'+f.key).disabled&&!$('#p-'+f.key).closest('.field').hidden)values[f.label.replace(/<[^>]+>/g,'')+(f.unit?' ('+f.unit+')':'')]=params[f.key];Object.assign(values,out);records.push({id:Date.now()+'-'+Math.random().toString(16).slice(2),experiment:active.id,title:active.title,date:new Date().toISOString(),time,params:{...params},values});persist();toast('Вимір записано. Відкрий журнал для графіка й CSV.')}
$('#journalOpen').onclick=()=>{fillJournal();$('#journal').showModal();requestAnimationFrame(plotJournal)};$('#journalClose').onclick=()=>$('#journal').close();$('#journal').onclick=ev=>{if(ev.target===$('#journal')){let r=$('#journal').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#journal').close()}};$('#clear').onclick=()=>{if(!records.length)return;if(confirm('Видалити всі записи з цього браузера? Спочатку збережи CSV, якщо потрібна копія.')){records=[];persist();fillJournal();plotJournal()}};
function fillJournal(){let selected=$('#plotExp').value;let options=exps.filter(e=>records.some(r=>r.experiment===e.id));$('#plotExp').innerHTML=options.length?options.map(e=>`<option value="${e.id}">${e.title}</option>`).join(''):'<option value="">Немає вимірів</option>';if(options.some(e=>e.id===selected))$('#plotExp').value=selected;else if(active&&options.some(e=>e.id===active.id))$('#plotExp').value=active.id;fillAxes();$('#rows').innerHTML=records.length?`<table><thead><tr><th>№</th><th>Дослід</th><th>Час анімації, с (якщо є)</th><th>Результат</th><th></th></tr></thead><tbody>${records.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.title)}</td><td>${animatedIds.includes(r.experiment)?number(r.time):'—'}</td><td>${Object.entries(r.values).slice(-3).map(([k,v])=>`${mathMarkup(esc(k))}: ${number(v)}`).join('; ')}</td><td><button data-remove="${r.id}" aria-label="Видалити вимір ${i+1}">×</button></td></tr>`).join('')}</tbody></table>`:'<p>Ще немає вимірів. Відкрий дослід і натисни «Записати вимір».</p>';$('#rows').onclick=ev=>{let id=ev.target.closest('[data-remove]')?.dataset.remove;if(id){records=records.filter(r=>r.id!==id);persist();fillJournal();plotJournal()}}}
function plainLabel(k){return k.replaceAll('I/Iвх','(частка початкової інтенсивності)').replaceAll('Kmax','Максимальна кінетична енергія').replaceAll('Bλ','Спектральна яскравість').replaceAll('R☉','сонячних радіусів').replaceAll('L☉','сонячних світностей').replace(/<[^>]*>/g,'')}
function fillAxes(){let relevant=records.filter(r=>r.experiment===$('#plotExp').value),keys=[...new Set(relevant.flatMap(r=>Object.keys(r.values)))];for(let s of ['#plotX','#plotY'])$(s).innerHTML=keys.map(k=>`<option value="${esc(k)}">${esc(plainLabel(k))}</option>`).join('');if(keys.length>1)$('#plotY').selectedIndex=keys.length-1;}
let journalData={pts:[]};function plotJournal(hover=null){let x=$('#plotX').value,y=$('#plotY').value;let pts=records.filter(r=>r.experiment===$('#plotExp').value).map(r=>[r.values[x],r.values[y]]).filter(q=>q.every(Number.isFinite)).sort((a,b)=>a[0]-b[0]);journalData={pts,xlabel:x,ylabel:y,scatter:true};let nearest=drawChart($('#journalPlot'),journalData,hover);if(nearest)$('#plotRead').textContent=`${x}: ${number(nearest[0])} · ${y}: ${number(nearest[1])}`}
$('#plotExp').onchange=()=>{fillAxes();plotJournal()};$('#plotX').onchange=$('#plotY').onchange=()=>plotJournal();$('#journalPlot').addEventListener('pointermove',ev=>plotJournal(ev.clientX-ev.currentTarget.getBoundingClientRect().left));$('#csv').onclick=()=>{if(!records.length){toast('Спочатку запиши вимір у досліді.');return}let headers=['номер','дата_ISO','дослід','час_анімації_с','параметр_або_результат','значення','налаштування_JSON'],rows=[headers];records.forEach((r,i)=>Object.entries(r.values).forEach(([k,v])=>rows.push([i+1,r.date,r.title,animatedIds.includes(r.experiment)?r.time:'',k,Number.isFinite(v)?v:'',JSON.stringify(r.params)])));let csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='INSCIENCE-Svitlo-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV підготовлено. Один вимір містить кілька рядків результатів.')};
addEventListener('hashchange',route);addEventListener('resize',()=>{if(active)render();if($('#journal').open)plotJournal()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){running=false;cancelAnimationFrame(frame);updateButtons()}});persist();route();

function bindPrismViewport(){
 const canvas=$('#scene');let drag=null;
 const save=()=>{try{sessionStorage.setItem('light-params-refraction',JSON.stringify(params))}catch{}};
 const draw=()=>{render();save()};
 canvas.addEventListener('pointerdown',ev=>{if(!params.prism||ev.button!==0||drag)return;ev.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(ev.pointerId);drag={id:ev.pointerId,x:ev.clientX,y:ev.clientY,px:params.panX||0,py:params.panY||0};canvas.classList.add('dragging')});
 canvas.addEventListener('pointermove',ev=>{if(!drag||ev.pointerId!==drag.id)return;const b=canvas.getBoundingClientRect();params.panX=drag.px+(ev.clientX-drag.x)/b.width;params.panY=drag.py+(ev.clientY-drag.y)/b.height;render()});
 const end=ev=>{if(!drag||ev.pointerId!==drag.id)return;drag=null;canvas.classList.remove('dragging');save()};
 canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);
 canvas.addEventListener('keydown',ev=>{if(!params.prism)return;const d={ArrowLeft:[-.05,0],ArrowRight:[.05,0],ArrowUp:[0,-.05],ArrowDown:[0,.05]}[ev.key];if(d){ev.preventDefault();params.panX=(params.panX||0)+d[0];params.panY=(params.panY||0)+d[1];draw()}else if(ev.key==='Home'){ev.preventDefault();$('#prismHome').click()}});
 $('#prismHome').onclick=()=>{params.panX=0;params.panY=0;params.prismZoom=1;params.prismView='overview';$('#p-prismZoom').value=1;$('#o-prismZoom').textContent='1 ×';$('#p-prismView').value='overview';draw()};
}
